def crack_xor_key(cipher, known_plain):
    if len(cipher) < len(known_plain):
        return None

    # Try to find the key by XORing known plaintext with corresponding cipher bytes
    # The key repeats, so we can try different key lengths
    for key_len in range(1, len(known_plain) + 1):
        # Extract potential key from the first key_len bytes
        potential_key = []
        for i in range(key_len):
            if i < len(cipher):
                potential_key.append(cipher[i] ^ ord(known_plain[i]))

        # Verify this key works for the entire cipher
        valid = True
        for i in range(len(cipher)):
            if cipher[i] != (potential_key[i % key_len] ^ ord(known_plain[i % len(known_plain)])):
                valid = False
                break

        if valid:
            return bytes(potential_key)

    return None
