import re

def extract_strings(blob):
    # Extract ASCII strings of length >= 4
    ascii_strings = re.findall(rb'[ -~]{4,}', blob)

    # Extract UTF-16 strings of length >= 4
    utf16_strings = []
    for i in range(0, len(blob) - 7, 2):
        # Check for null-terminated UTF-16 string
        if blob[i:i+2] == b'\x00\x00':
            continue
        # Look for a sequence of valid UTF-16 characters
        utf16_chars = []
        j = i
        while j < len(blob) - 1 and blob[j:j+2] != b'\x00\x00':
            if blob[j:j+2] == b'\x00\x00':
                break
            # Check if it's a valid UTF-16 character (simplified check)
            if 0x20 <= blob[j] <= 0x7E and 0x20 <= blob[j+1] <= 0x7E:
                utf16_chars.append(blob[j:j+2])
            else:
                break
            j += 2
        if len(utf16_chars) >= 4:
            utf16_strings.append(b''.join(utf16_chars))

    # Combine and return all strings
    result = []
    for s in ascii_strings:
        try:
            decoded = s.decode('ascii')
            result.append(decoded)
        except UnicodeDecodeError:
            pass

    for s in utf16_strings:
        try:
            decoded = s.decode('utf-16-le')
            result.append(decoded)
        except UnicodeDecodeError:
            pass

    return list(set(result))
